import{_ as e,o as s,c as i,ao as a}from"./chunks/framework.CvmVtbJQ.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"MPSKit.jl","text":"Matrix product states in Julia","tagline":"Efficient and versatile tools for working with matrix product states","image":{"src":"/logo.svg","alt":"MPSKit.jl"},"actions":[{"theme":"brand","text":"Get started","link":"/tutorials/installation"},{"theme":"alt","text":"Examples","link":"/examples/"},{"theme":"alt","text":"View on GitHub","link":"https://github.com/QuantumKitHub/MPSKit.jl"}]},"features":[{"icon":"🔗","title":"States","details":"Construct and manipulate finite and infinite matrix product states (MPS)."},{"icon":"📏","title":"Observables","details":"Measure expectation values, correlations, and other observables."},{"icon":"🎯","title":"Optimization","details":"Ground states, time evolution, and excitations via DMRG, VUMPS, and more."},{"icon":"⚛️","title":"Symmetries","details":"Abelian, non-Abelian, fermionic, and anyonic symmetries out of the box."}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":null}'),n={name:"index.md"};function r(o,t,l,h,p,d){return s(),i("div",null,[...t[0]||(t[0]=[a(`<p>MPSKit.jl is a Julia library for simulating one-dimensional quantum many-body systems with matrix product states and operators. It provides both finite and infinite MPS, a range of ground-state, time-evolution, and excitation algorithms, and support for arbitrary symmetries through the <a href="https://github.com/Jutho/TensorKit.jl" target="_blank" rel="noreferrer">TensorKit.jl</a> tensor backend. It is aimed at researchers and students who want to run tensor-network calculations without reimplementing the underlying machinery.</p><h2 id="Installation" tabindex="-1">Installation <a class="header-anchor" href="#Installation" aria-label="Permalink to &quot;Installation {#Installation}&quot;">​</a></h2><p>MPSKit.jl is a part of the general registry. Together with the packages used throughout this documentation, it can be installed via the package manager as:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pkg&gt; add MPSKit TensorKit TensorOperations MPSKitModels TensorKitTensors Plots</span></span></code></pre></div><ul><li><p><code>MPSKit</code> provides the matrix product state and operator types, together with the ground-state, time-evolution, and bond-dimension algorithms.</p></li><li><p><code>TensorKit</code> supplies the tensor backend (<code>TensorMap</code>s and vector spaces) that MPSKit is built on; installing it alongside MPSKit also gives access to truncation-scheme constructors such as <code>truncrank</code>, which TensorKit re-exports from MatrixAlgebraKit.</p></li><li><p><code>TensorOperations</code> provides the <code>@tensor</code> macro for contracting tensors by hand.</p></li><li><p><code>MPSKitModels</code> collects pre-defined Hamiltonians and local operators for common physical models.</p></li><li><p><code>TensorKitTensors</code> provides ready-made local operators, such as the Pauli operators used throughout the documentation.</p></li><li><p><code>Plots</code> is used to visualize results in several of the how-to guides and examples.</p></li></ul><p>For a step-by-step walkthrough that sets up a dedicated environment and verifies the installation, see <a href="/MPSKit.jl/previews/PR451/tutorials/installation#tutorial_installation">Installation</a>.</p><h2 id="A-30-second-example" tabindex="-1">A 30-second example <a class="header-anchor" href="#A-30-second-example" aria-label="Permalink to &quot;A 30-second example {#A-30-second-example}&quot;">​</a></h2><p>Finding the ground state of the transverse-field Ising chain takes a handful of lines.</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> MPSKit, MPSKitModels, TensorKit</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">H </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> transverse_field_ising</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">FiniteChain</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">16</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">); g </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ψ₀ </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> FiniteMPS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">16</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, ℂ</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">^</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, ℂ</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">^</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ψ, envs, ϵ </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> find_groundstate</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(ψ₀, H, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">DMRG</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(; verbosity </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">E </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> expectation_value</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(ψ, H)</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;">-16.146039498683976 - 4.4176709669413745e-15im</span></span></code></pre></div><p>For a guided version of this calculation that explains each step and measures more observables, see <a href="/MPSKit.jl/previews/PR451/tutorials/first_groundstate#tutorial_first_groundstate">Your first ground state</a>.</p><h2 id="Where-next" tabindex="-1">Where next <a class="header-anchor" href="#Where-next" aria-label="Permalink to &quot;Where next {#Where-next}&quot;">​</a></h2><p><strong>Tutorials</strong> walk you through complete calculations from scratch. Start with <a href="/MPSKit.jl/previews/PR451/tutorials/installation#tutorial_installation">Installation</a>, then run <a href="/MPSKit.jl/previews/PR451/tutorials/first_groundstate#tutorial_first_groundstate">Your first ground state</a>, and continue to <a href="/MPSKit.jl/previews/PR451/tutorials/thermodynamic_limit#tutorial_thermodynamic_limit">The thermodynamic limit</a> to work directly at infinite system size.</p><p><strong>How-to guides</strong> are focused task recipes for when you already know what you want to do. See <a href="/MPSKit.jl/previews/PR451/howto/states#howto_states">Constructing states</a>, <a href="/MPSKit.jl/previews/PR451/howto/hamiltonians#howto_hamiltonians">Building Hamiltonians</a>, and <a href="/MPSKit.jl/previews/PR451/howto/observables#howto_observables">Computing observables</a>, among others.</p><p><strong>The manual</strong> explains the concepts behind the library — the <a href="/MPSKit.jl/previews/PR451/man/states#um_states">States</a>, <a href="/MPSKit.jl/previews/PR451/man/operators#um_operators">Operators</a>, and <a href="/MPSKit.jl/previews/PR451/man/algorithms#um_algorithms">Algorithms</a> that make up MPSKit.</p><p><strong>The examples</strong> gallery collects longer, fully worked scripts covering symmetries, infinite systems, and less common algorithms; browse it at <a href="/MPSKit.jl/previews/PR451/examples/index#Examples">Examples</a>.</p><p><strong>The library</strong> is the API reference; the curated, stable entry point is the <a href="/MPSKit.jl/previews/PR451/lib/public#public_api">Public API</a>.</p><h2 id="Ecosystem" tabindex="-1">Ecosystem <a class="header-anchor" href="#Ecosystem" aria-label="Permalink to &quot;Ecosystem {#Ecosystem}&quot;">​</a></h2><p>MPSKit builds on <a href="https://github.com/Jutho/TensorKit.jl" target="_blank" rel="noreferrer">TensorKit.jl</a>, which supplies the tensors and vector spaces and handles the symmetries. Models and ready-made operators come from <a href="https://github.com/QuantumKitHub/MPSKitModels.jl" target="_blank" rel="noreferrer">MPSKitModels.jl</a> and <a href="https://github.com/QuantumKitHub/TensorKitTensors.jl" target="_blank" rel="noreferrer">TensorKitTensors.jl</a>. All of these are part of the <a href="https://github.com/QuantumKitHub" target="_blank" rel="noreferrer">QuantumKitHub</a> organization; the TensorKit documentation is available <a href="https://quantumkithub.github.io/TensorKit.jl/stable/" target="_blank" rel="noreferrer">here</a>.</p><h2 id="Community-and-support" tabindex="-1">Community and support <a class="header-anchor" href="#Community-and-support" aria-label="Permalink to &quot;Community and support {#Community-and-support}&quot;">​</a></h2><p>Questions and general discussion are welcome on <a href="https://github.com/QuantumKitHub/MPSKit.jl/discussions" target="_blank" rel="noreferrer">GitHub Discussions</a>; bug reports belong on the <a href="https://github.com/QuantumKitHub/MPSKit.jl/issues" target="_blank" rel="noreferrer">issue tracker</a>. If you would like to contribute, see <a href="https://github.com/QuantumKitHub/MPSKit.jl/blob/main/CONTRIBUTING.md" target="_blank" rel="noreferrer">CONTRIBUTING.md</a> on GitHub.</p>`,21)])])}const k=e(n,[["render",r]]);export{c as __pageData,k as default};
